/// <summary>
///     The <c>AVASalesInvoiceJournalPostCls_Extension</c> class is the extension for <c>SalesInvoiceJournalPost</c>
/// </summary>
[ExtensionOf(classStr(SalesInvoiceJournalPost))]
final class AVASalesInvoiceJournalPostCls_Extension
{
}

Method.Source:
/// <summary>
///    AVA <c>updateSourceTable</c> method.
/// </summary>
protected void updateSourceTable()
{
    SetEnumerator   locSE;
    SalesTable      locSalesTable;

    next updateSourceTable();

    ttsbegin;
    locSE = ordersPosted.getEnumerator();

    while (locSE.moveNext())
    {
        locSalesTable = SalesTable::find(locSE.current(), true);
        if (locSalesTable.RecId)
        {
            locSalesTable.avaUpdateFreightInformationAfterIPost();
        }
    }
    ttscommit;
}

/// <summary>
///    AVA <c>postJournalPost</c> method.
/// </summary>
public void postJournalPost()
{
    CustPackingSlipJour locCustPackingSlipJour;
    SalesTable          locSalesTable;
    //boolean             handleCollectionCommission;

    next postJournalPost();

    locSalesTable   = custInvoiceJour.SalesTable();

    select firstonly locCustPackingSlipJour
    where   locCustPackingSlipJour.PackingSlipId    == locSalesTable.lastPackingSlip()
        &&  locCustPackingSlipJour.SalesId          == locSalesTable.SalesId;

    if(locSalesTable.avaNeedMarkupForFreightCharge(locCustPackingSlipJour.DlvMode))
    {
        locSalesTable.avaAddMarkupCollectionCommision();
    }
}
